const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define three regions
  const eastMidlands = ee.Geometry.Polygon([
    [[-2.5, 52.8], [-0.5, 52.8], [-0.5, 51.8], [-2.5, 51.8], [-2.5, 52.8]]
  ]);

  const northeastEngland = ee.Geometry.Polygon([
    [[-2.5, 55.0], [-0.5, 55.0], [-0.5, 54.2], [-2.5, 54.2], [-2.5, 55.0]]
  ]);

  const easternScotland = ee.Geometry.Polygon([
    [[-2.5, 57.0], [-0.5, 57.0], [-0.5, 55.8], [-2.5, 55.8], [-2.5, 57.0]]
  ]);

  const regions = [
    { name: 'East Midlands', geom: eastMidlands },
    { name: 'Northeast England', geom: northeastEngland },
    { name: 'Eastern Scotland', geom: easternScotland }
  ];

  // Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  let allResults = [];

  for (const region of regions) {
    print(`\n=== ${region.name} ===`);

    // October 2023 and January 2024
    const oct2023 = chirps
      .filterDate('2023-10-01', '2023-10-31')
      .filterBounds(region.geom);
    const jan2024 = chirps
      .filterDate('2024-01-01', '2024-01-04')
      .filterBounds(region.geom);

    const oct2023Size = oct2023.size().getInfo();
    const jan2024Size = jan2024.size().getInfo();

    if (oct2023Size === 0 || jan2024Size === 0) {
      print(`Data missing: Oct2023=${oct2023Size}, Jan2024=${jan2024Size}`);
      print('Result: C1');
      allResults.push('C1');
      continue;
    }

    // Calculate total rainfall for Oct 2023 and Jan 2024
    const oct2023Total = oct2023.sum().reduceRegion(
      ee.Reducer.mean(),
      region.geom,
      1000,
      1e9
    ).get('precipitation').getInfo();

    const jan2024Total = jan2024.sum().reduceRegion(
      ee.Reducer.mean(),
      region.geom,
      1000,
      1e9
    ).get('precipitation').getInfo();

    if (oct2023Total === null || jan2024Total === null) {
      print('Calculation failed (null values)');
      print('Result: C3');
      allResults.push('C3');
      continue;
    }

    // Calculate 1991-2020 average for October and January
    const octAvg1991_2020 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filter(ee.Filter.calendarRange(10, 10, 'month'))
      .filter(ee.Filter.calendarRange(1991, 2020, 'year'))
      .filterBounds(region.geom)
      .sum()
      .reduceRegion(
        ee.Reducer.mean(),
        region.geom,
        1000,
        1e9
      ).get('precipitation').getInfo();

    const janAvg1991_2020 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filter(ee.Filter.calendarRange(1, 1, 'month'))
      .filter(ee.Filter.calendarRange(1991, 2020, 'year'))
      .filterBounds(region.geom)
      .sum()
      .reduceRegion(
        ee.Reducer.mean(),
        region.geom,
        1000,
        1e9
      ).get('precipitation').getInfo();

    if (octAvg1991_2020 === null || janAvg1991_2020 === null) {
      print('Historical average calculation failed');
      print('Result: C3');
      allResults.push('C3');
      continue;
    }

    const recent = oct2023Total + jan2024Total;
    const historical = octAvg1991_2020 + janAvg1991_2020;

    print(`Oct 2023: ${oct2023Total.toFixed(1)} mm`);
    print(`Jan 2024: ${jan2024Total.toFixed(1)} mm`);
    print(`Oct Avg (1991-2020): ${octAvg1991_2020.toFixed(1)} mm`);
    print(`Jan Avg (1991-2020): ${janAvg1991_2020.toFixed(1)} mm`);
    print(`Recent Total: ${recent.toFixed(1)} mm`);
    print(`Historical Avg: ${historical.toFixed(1)} mm`);

    if (recent > historical) {
      print('Result: YES (more rain in 2023-2024)');
      allResults.push('A');
    } else {
      print('Result: NO (less or equal rain in 2023-2024)');
      allResults.push('B');
    }
  }

  // Summary: If all regions show more rain, answer A; if mixed/all show less, answer B
  print(`\n=== SUMMARY ===`);
  print(`Results: ${allResults.join(', ')}`);

  const yesCount = allResults.filter(r => r === 'A').length;
  const noCount = allResults.filter(r => r === 'B').length;

  if (allResults.includes('C1') || allResults.includes('C3')) {
    print(allResults.includes('C1') ? 'C1' : 'C3');
  } else if (yesCount > noCount) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
